INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A financial services company needs to build a complex data pipeline that involves multiple interdependent steps: data ingestion, transformation, validation, and loading. Each step is implemented as an AWS Lambda function or an AWS Glue job. The pipeline requires robust error handling, automatic retries, and visual tracking of execution progress to ensure compliance and auditability. Which AWS service should be used to orchestrate this pipeline with the LEAST operational overhead?', '["Develop a custom Python script on an Amazon EC2 instance to sequentially invoke Lambda functions and Glue jobs.","Use AWS Step Functions to define and orchestrate the workflow, integrating Lambda and Glue as state machine steps.","Configure AWS Glue Workflows to manage the dependencies and execution of the Lambda functions and Glue jobs.","Schedule individual AWS Lambda functions and AWS Glue jobs using Amazon EventBridge rules."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable choice. AWS Step Functions provides a serverless workflow orchestration service that allows defining complex, multi-step workflows using state machines. It offers built-in error handling, automatic retries, parallel execution, and visual tracking of execution progress, making it ideal for complex pipelines with Lambda and Glue, all with minimal operational overhead. Option A (incorrect) requires managing an Amazon EC2 instance and developing custom orchestration logic, which significantly increases operational overhead and complexity (anti-pattern ap-1.3-001). Option C (incorrect) is designed primarily for orchestrating AWS Glue jobs and may not be as flexible or robust for integrating diverse services like AWS Lambda functions with complex conditional logic and advanced error handling compared to Step Functions. Option D (incorrect) is suitable for simple, time-based or event-driven triggers for individual jobs but lacks the ability to define complex dependencies, conditional logic, and built-in error handling across multiple interdependent steps in a single, cohesive workflow.', 32, 'm_32_3', 6, NULL, NULL),
  ('mock_32_all_1775005113845', 'A retail analytics platform needs to orchestrate a data pipeline that includes both batch processing (AWS Glue) and real-time stream processing (Amazon Kinesis Data Analytics). The workflow is complex, with conditional logic, parallel branches, and external system integrations. The data engineering team is already familiar with Apache Airflow and prefers to use an Airflow-compatible solution on AWS. Which service should they choose?', '["AWS Step Functions for serverless orchestration.","AWS Glue Workflows for ETL job dependency management.","Amazon Managed Workflows for Apache Airflow (MWAA).","Amazon EventBridge for schedule-based and event-driven triggers."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the ideal choice. Amazon Managed Workflows for Apache Airflow (MWAA) provides a fully managed service for deploying and operating Apache Airflow. Since the team is already familiar with Airflow and the pipeline involves complex, multi-service workflows with conditional logic and external integrations, MWAA allows them to leverage their existing Airflow knowledge and DAGs while benefiting from a managed service. Option A (incorrect) is a powerful serverless orchestrator but might require rewriting existing Airflow DAGs into Step Functions state language, which is not ideal if Airflow compatibility is a key requirement. Option B (incorrect) is primarily designed for orchestrating AWS Glue jobs and lacks the broader ecosystem and flexibility of Apache Airflow for integrating diverse services and complex logic. Option D (incorrect) is suitable for simple event-driven or schedule-based triggers but is not a full-fledged workflow orchestrator for complex, multi-step pipelines with dependencies.', 32, 'm_32_3', 7, NULL, NULL),
  ('mock_32_all_1775005113845', 'A healthcare provider receives patient data files hourly in an Amazon S3 bucket. Upon arrival, a series of data validation and anonymization steps must be executed. If any step fails, the pipeline should stop, and an alert should be sent to the operations team. The solution must be serverless, event-driven, and provide clear state management for auditing purposes. Which combination of services meets these requirements?', '["Configure Amazon S3 event notifications to trigger an AWS Step Functions workflow that orchestrates AWS Lambda functions for validation and anonymization, with Amazon SNS for alerts.","Use AWS Glue Workflows to manage the data validation and anonymization steps, triggered by an Amazon EventBridge rule.","Deploy an Amazon EC2 instance running a custom Python script that polls the S3 bucket, processes files, and sends alerts via Amazon SQS.","Set up individual AWS Lambda functions for each step, chained together by invoking each other, and use Amazon CloudWatch Alarms for error detection."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a robust, serverless, and event-driven solution. Amazon S3 event notifications can trigger an AWS Step Functions state machine, which is excellent for orchestrating sequential steps (AWS Lambda functions for validation and anonymization), handling errors, retries, and providing visual state tracking. Amazon SNS can be integrated into the Step Functions workflow for alerts upon failure. Option B (incorrect) is primarily for orchestrating AWS Glue jobs and might not be as suitable for a purely serverless, Lambda-centric workflow with complex state management and direct SNS integration for alerts outside of Glue''s native notification capabilities. Option C (incorrect) involves managing an Amazon EC2 instance, which introduces operational overhead and is not a serverless solution (anti-pattern ap-1.3-001). Option D (incorrect) creates a tightly coupled, hard-to-manage chain of Lambda functions. Debugging and monitoring state across multiple Lambda invocations become complex, and CloudWatch Alarms would detect errors but not provide the structured workflow state management of Step Functions.', 32, 'm_32_3', 8, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data platform team wants to trigger an AWS Glue ETL job at 2 AM UTC every day. They need a simple, reliable, and serverless mechanism to schedule this job without provisioning or managing any compute resources for the scheduler itself. Which AWS service should they use to achieve this with the LEAST operational overhead?', '["Use AWS Step Functions to define a workflow that includes the Glue job and schedule it with a custom cron expression.","Create an Amazon EventBridge rule with a schedule expression (cron or rate) to trigger the AWS Glue job.","Deploy an Amazon EC2 instance and configure a cron job to invoke the AWS Glue job using the AWS CLI.","Use AWS Glue Workflows and configure its start trigger to be a daily schedule."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most straightforward and serverless solution for simple time-based scheduling. Amazon EventBridge (formerly CloudWatch Events) allows creating rules with schedule expressions (cron or rate) that can directly trigger AWS Glue jobs. This requires no server management and minimal configuration. Option A (incorrect) is an over-engineered solution for a simple daily schedule. While Step Functions can be scheduled, it''s more suited for complex, multi-step workflows, not just a single job trigger. Option C (incorrect) requires provisioning and managing an Amazon EC2 instance, which adds significant operational overhead and is not a serverless approach (anti-pattern ap-1.3-001). Option D (incorrect) is a valid option if the Glue job is part of a larger Glue workflow. However, for a single, independent Glue job, an EventBridge rule is simpler and has less overhead than setting up a full Glue Workflow just for scheduling.', 32, 'm_32_3', 9, NULL, NULL);

