INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A gaming company needs to ingest real-time clickstream data from millions of concurrent users into a data lake for immediate analytics. The data volume can fluctuate significantly, from thousands to millions of records per second. The solution must automatically scale to handle spikes and deliver data to Amazon S3 with minimal operational overhead. Which service combination should they choose?', '["Use AWS Glue streaming ETL jobs to ingest data directly from client applications to Amazon S3.","Implement an Amazon EC2 fleet running Apache Kafka to collect clickstream data and write to Amazon S3.","Utilize Amazon Kinesis Data Firehose to ingest data directly from client applications and deliver it to Amazon S3.","Configure Amazon Kinesis Data Streams to ingest data, then use AWS Lambda to write each record to Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable solution. Amazon Kinesis Data Firehose is a fully managed service that automatically scales to handle varying data volumes and delivers streaming data directly to Amazon S3 (among other destinations). It requires minimal operational overhead as there are no servers to manage. Option A (incorrect) is not designed for direct real-time ingestion from client applications at scale; AWS Glue streaming ETL jobs typically process data from existing streaming sources like Kinesis or MSK. Option B (incorrect) requires managing an Amazon EC2 fleet and Apache Kafka clusters, which introduces significant operational overhead and is not a fully managed solution. Option D (incorrect) involves using Amazon Kinesis Data Streams, which is good for custom real-time processing, but using AWS Lambda to write each record individually to Amazon S3 is inefficient and costly for high-volume streaming data. Kinesis Data Firehose is optimized for bulk delivery to S3 (anti-pattern ap-1.1-002).', 32, 'm_32_1', 10, NULL, NULL),
  ('mock_32_all_1775005113845', 'A large enterprise wants to migrate several terabytes of historical on-premises data from their Network File System (NFS) shares to Amazon S3 for long-term archival and future analytics. The migration needs to be secure, efficient, and minimize manual effort. The data transfer should be optimized for network bandwidth and automatically handle retries. Which AWS service is designed for this specific migration scenario?', '["Use AWS DMS (Database Migration Service) to transfer files from NFS to Amazon S3.","Deploy an Amazon EC2 instance and use the AWS CLI `aws s3 sync` command to copy data.","Leverage AWS DataSync to automate and accelerate the transfer of data from on-premises NFS to Amazon S3.","Utilize Amazon Kinesis Data Firehose to stream the on-premises data to Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the ideal service for this scenario. AWS DataSync is specifically designed for large-scale, online data transfer from on-premises storage systems (like NFS shares) to AWS storage services like Amazon S3. It automates data transfer, handles network optimizations, retries, and provides security and monitoring, minimizing manual effort. Option A (incorrect) is primarily for migrating databases and data warehouses, not file systems. Option B (incorrect) requires provisioning and managing an Amazon EC2 instance, and while `aws s3 sync` can copy data, it lacks the optimization, automation, and robust error handling of DataSync for large-scale migrations. Option D (incorrect) is a streaming ingestion service for real-time data, not suitable for migrating large volumes of historical batch data from an NFS share.', 32, 'm_32_1', 11, NULL, NULL),
  ('mock_32_all_1775005113845', 'A company needs to capture change data from an Amazon RDS PostgreSQL database and deliver it to Amazon S3 for auditing and near real-time analytics. The solution should continuously replicate changes (inserts, updates, deletes) without significantly impacting the source database''s performance. Which AWS service should be used to achieve this continuous change data capture (CDC)?', '["Configure an AWS Glue ETL job to perform daily full table scans and write changes to Amazon S3.","Develop a custom application on Amazon EC2 to read database transaction logs and push changes to Amazon S3.","Utilize AWS DMS (Database Migration Service) to set up a continuous replication task from Amazon RDS to Amazon S3.","Export database snapshots periodically from Amazon RDS and store them in Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate solution. AWS DMS (Database Migration Service) is specifically designed for migrating databases and performing continuous data replication (CDC) from various sources, including Amazon RDS, to targets like Amazon S3. It captures changes from the source database''s transaction logs with minimal impact on performance. Option A (incorrect) involves daily full table scans, which is a batch approach, not continuous CDC, and can be resource-intensive, failing the ''near real-time'' and ''minimal impact'' requirements. Option B (incorrect) requires significant development effort, infrastructure management (EC2), and maintenance for a custom solution, which is less efficient and more complex than a managed service. Option D (incorrect) provides point-in-time recovery but does not offer continuous, near real-time change data capture.', 32, 'm_32_1', 12, NULL, NULL),
  ('mock_32_all_1775005113845', 'An IoT platform collects sensor data from thousands of devices. This data needs to be ingested into a streaming platform for real-time processing by custom applications and then archived to Amazon S3 for long-term storage and batch analytics. The custom applications require direct access to the raw stream for complex, stateful processing. Which AWS service combination should be used?', '["Ingest data directly into Amazon Kinesis Data Firehose, which delivers to Amazon S3.","Use Amazon Kinesis Data Streams for ingestion, and then configure Amazon Kinesis Data Firehose to deliver data from the stream to Amazon S3.","Set up Amazon MSK (Managed Streaming for Apache Kafka) for ingestion and use AWS Glue streaming jobs to write to Amazon S3.","Deploy an Amazon EC2 instance with a custom application to ingest data and write to both Amazon S3 and a local file system."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution. Amazon Kinesis Data Streams is designed for ingesting and processing real-time streaming data, allowing custom applications to consume records directly from the stream for complex, stateful processing. Amazon Kinesis Data Firehose can then be configured as a consumer of the Kinesis Data Stream to reliably deliver the data to Amazon S3 for archival and batch analytics, providing a fully managed and scalable solution. Option A (incorrect) only uses Kinesis Data Firehose, which is excellent for direct delivery to S3 but does not allow custom applications direct access to the raw stream for complex processing. Option C (incorrect) is a viable option if the team specifically requires Apache Kafka compatibility, but for general streaming and custom application processing with S3 archival, Kinesis Data Streams and Firehose are often simpler and fully managed. Option D (incorrect) involves managing an Amazon EC2 instance and developing custom ingestion logic, which introduces significant operational overhead and is not a fully managed solution.', 32, 'm_32_1', 13, NULL, NULL),
  ('mock_32_all_1775005113845', 'A retail company wants to collect customer interaction events from their website and mobile applications. These events are sent via an API Gateway endpoint. The data needs to be ingested into a streaming service for real-time analytics and then eventually stored in Amazon S3 for batch processing. The solution should be serverless, scalable, and handle millions of events per hour. Which architecture should be implemented?', '["API Gateway directly writes events to Amazon S3, and an AWS Glue job processes them hourly.","API Gateway triggers an AWS Lambda function, which then writes events directly to an Amazon DynamoDB table.","API Gateway triggers an AWS Lambda function, which then publishes events to an Amazon Kinesis Data Streams, and Kinesis Data Firehose delivers data to Amazon S3.","API Gateway triggers an Amazon SQS queue, and an Amazon EC2 instance polls the queue to process and store events in Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a robust, serverless, and scalable architecture for API-based streaming ingestion. API Gateway handles incoming requests, AWS Lambda performs lightweight processing and publishes events to Amazon Kinesis Data Streams for real-time analytics. Kinesis Data Firehose can then be configured as a consumer of the Kinesis Data Stream to reliably deliver the data to Amazon S3 for batch processing and long-term storage. Option A (incorrect) is a batch ingestion pattern (anti-pattern ap-1.1-001) and does not support real-time analytics. Option B (incorrect) uses Amazon DynamoDB, which is a NoSQL database, but it''s not primarily a streaming ingestion service for real-time analytics and large-scale data lake storage. Option D (incorrect) involves managing an Amazon EC2 instance, which introduces operational overhead and is not a fully serverless solution for streaming ingestion.', 32, 'm_32_1', 14, NULL, NULL);

