INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A data analytics team needs to perform complex ETL transformations on large datasets (several terabytes) stored in Amazon S3. The transformations involve joining multiple large tables, filtering, and aggregating data. The team requires a serverless, scalable solution that can handle PySpark jobs without managing underlying infrastructure, to minimize operational overhead. Which AWS service is best suited for this task?', '["Use AWS Lambda functions with increased memory for the PySpark transformations.","Provision an Amazon EMR cluster to run the PySpark jobs.","Utilize Amazon Kinesis Data Analytics for Apache Flink to process the data.","Employ AWS Glue ETL jobs with PySpark to perform the transformations."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate solution. AWS Glue ETL jobs support PySpark and are designed for large-scale data processing. As a serverless service, AWS Glue automatically provisions, configures, and scales the underlying Apache Spark environment, minimizing operational overhead for the data engineering team. Option A (incorrect) is an anti-pattern (ap-1.2-001) because AWS Lambda has a 15-minute timeout and limited memory, making it unsuitable for heavy, long-running ETL transforms over large datasets. Option B (incorrect) is a powerful option for running PySpark jobs but requires provisioning and managing an Amazon EMR cluster, which increases operational overhead compared to a serverless solution like AWS Glue. Option C (incorrect) is primarily for real-time streaming analytics using Apache Flink, not for batch ETL transformations of large datasets stored in Amazon S3.', 32, 'm_32_2', 15, NULL, NULL),
  ('mock_32_all_1775005113845', 'A company processes daily logs from various applications, storing them as JSON files in Amazon S3. They need to transform these logs into a columnar format like Parquet, partition them by date, and store them back in S3. This process should be automated and cost-effective for ad-hoc queries using Amazon Athena. Which solution is MOST cost-effective and efficient?', '["Use AWS Glue ETL jobs to read JSON, transform to Parquet, and write partitioned data back to Amazon S3, with an AWS Glue Data Catalog crawler to register the schema.","Deploy an Amazon EC2 instance with a custom Python script to convert and partition the data, then upload to Amazon S3.","Utilize AWS Lambda functions to process each JSON file individually, convert to Parquet, and upload to Amazon S3.","Store the JSON files directly in Amazon S3 and query them with Amazon Athena without transformation or partitioning."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and efficient solution. AWS Glue ETL jobs are serverless and scalable for transforming large datasets, converting JSON to Parquet, and writing partitioned data to Amazon S3. Partitioning data is crucial for cost-effective querying with Amazon Athena (anti-pattern ap-1.2-002), as it reduces the amount of data scanned. An AWS Glue Data Catalog crawler automatically discovers and registers the schema, making the data queryable. Option B (incorrect) requires managing an Amazon EC2 instance, which adds operational overhead and is less scalable and cost-effective than a serverless Glue job. Option C (incorrect) is an anti-pattern (ap-1.2-001) because AWS Lambda is not suitable for heavy, long-running ETL transforms over potentially large datasets, and processing files individually can be less efficient than batch processing. Option D (incorrect) is highly inefficient and costly for Amazon Athena queries because it would require full table scans of unpartitioned JSON data, violating the cost-effectiveness requirement (anti-pattern ap-1.2-002).', 32, 'm_32_2', 16, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data engineering team needs to perform real-time aggregations and transformations on a continuous stream of sensor data coming from Amazon Kinesis Data Streams. The transformed data will be used for live dashboards and anomaly detection, requiring sub-second latency. The solution must be fully managed and support SQL-like queries or Apache Flink applications. Which AWS service should be used?', '["Configure an AWS Glue streaming ETL job to process data from Amazon Kinesis Data Streams.","Use Amazon Kinesis Data Analytics (Amazon Managed Service for Apache Flink) to process the stream.","Deploy an Amazon EMR cluster with Apache Spark Streaming to process the data.","Write a custom application on Amazon EC2 to consume from Kinesis Data Streams and perform transformations."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the ideal service for real-time stream processing with sub-second latency. Amazon Kinesis Data Analytics (Amazon Managed Service for Apache Flink) is a fully managed service that allows running SQL queries or Apache Flink applications on streaming data, providing real-time transformations and aggregations without managing servers. Option A (incorrect) is suitable for streaming ETL but typically introduces higher latency compared to Kinesis Data Analytics, which is optimized for real-time processing. Option C (incorrect) requires provisioning and managing an Amazon EMR cluster, which increases operational overhead and is not a fully managed, serverless streaming solution. Option D (incorrect) involves managing an Amazon EC2 instance and developing a custom application, leading to significant operational overhead and maintenance.', 32, 'm_32_2', 17, NULL, NULL),
  ('mock_32_all_1775005113845', 'A research institution needs to process massive genomic datasets, often petabytes in size, using Apache Spark and Hive. They require a highly customizable and powerful distributed processing framework where they can fine-tune cluster configurations, install specific libraries, and manage job execution. The processing jobs are typically long-running batch operations. Which AWS service is best suited for this requirement?', '["AWS Glue ETL jobs for serverless Spark processing.","AWS Lambda functions for lightweight data transformations.","Amazon EMR for large-scale distributed data processing.","Amazon Kinesis Data Analytics for real-time stream processing."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable service. Amazon EMR provides a managed cluster platform that simplifies running big data frameworks like Apache Spark and Hive. It offers high customizability, allowing users to fine-tune cluster configurations, install specific software, and manage the underlying EC2 instances, which is crucial for petabyte-scale genomic datasets and long-running batch jobs. Option A (incorrect) is serverless and good for many ETL workloads, but for petabyte-scale data requiring deep customization of Spark/Hive environments, EMR offers more control. Option B (incorrect) is an anti-pattern (ap-1.2-001) as AWS Lambda is not designed for heavy, long-running processing of massive datasets. Option D (incorrect) is for real-time streaming analytics and not appropriate for large-scale batch processing of static genomic datasets.', 32, 'm_32_2', 18, NULL, NULL),
  ('mock_32_all_1775005113845', 'A small e-commerce company needs to perform simple data cleaning and enrichment on customer order data before loading it into a data warehouse. The transformation logic is straightforward, involves minimal data volume per batch (a few hundred records), and needs to run quickly in response to new file arrivals in Amazon S3. Which AWS service offers the MOST cost-effective and responsive solution for this task?', '["Provision an Amazon EMR cluster to run a Spark job for each new file.","Configure an AWS Glue ETL job to process each small batch of data.","Use AWS Glue DataBrew for visual data preparation and transformation.","Utilize an AWS Lambda function triggered by Amazon S3 events to perform the lightweight transformations."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most cost-effective and responsive solution for lightweight, event-driven transformations on small data volumes. An AWS Lambda function triggered by Amazon S3 events can quickly process individual files or small batches, executing only when needed and incurring costs only for compute time, making it highly efficient for this specific use case. Option A (incorrect) is an over-engineered and very expensive solution for small, lightweight transformations, as provisioning an Amazon EMR cluster for each small file would be highly inefficient. Option B (incorrect) is a serverless option, but AWS Glue ETL jobs are generally designed for larger-scale, more complex ETL workloads, and the startup time and cost per run might be higher than a Lambda function for very small, quick tasks. Option C (incorrect) is a data preparation tool that requires manual interaction or integration with Glue jobs for automated execution, which adds complexity and is not ideal for an automated, event-driven, lightweight transformation pipeline.', 32, 'm_32_2', 19, NULL, NULL);

