INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'An ad-tech company processes 5 TB of daily clickstream data, stored as uncompressed CSV files in an Amazon S3 bucket. Data analysts frequently run ad-hoc SQL queries to evaluate campaign performance, leading to unexpectedly high Amazon Athena costs. The company needs to reduce these query costs significantly. Which approach is MOST cost-effective for querying this data?', '["Convert the CSV data to Apache Parquet format, partition it by date, and query it using Amazon Athena.","Migrate all clickstream data to an Amazon Redshift cluster and perform queries there.","Use Amazon EMR Studio notebooks to write PySpark queries against the CSV data in Amazon S3.","Load the CSV data into Amazon QuickSight and use its SPICE engine for faster queries."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution. Amazon Athena charges based on the amount of data scanned. Converting uncompressed CSV data to a compressed, columnar format like Apache Parquet and partitioning it by a frequently queried dimension (like date) significantly reduces the amount of data Athena needs to scan, thereby lowering query costs by 85-97%. This directly addresses the anti-pattern of querying uncompressed, non-columnar S3 data with Athena.
Option B (incorrect) would introduce higher operational overhead and potentially higher costs for a managed data warehouse like Amazon Redshift, especially for ad-hoc querying needs, compared to the serverless nature of Athena. It''s not the most cost-effective for this specific scenario.
Option C (incorrect) involves Amazon EMR Studio, which provides a collaborative environment for Spark-based exploration but introduces more operational overhead and cost compared to serverless Athena for SQL queries. It also doesn''t inherently solve the cost issue of scanning uncompressed data without explicit data format conversion.
Option D (incorrect) uses Amazon QuickSight, which is a business intelligence service for visualization and dashboards. While SPICE can speed up queries, it''s not designed for raw ad-hoc SQL querying of large S3 datasets and would still require an underlying data source like Athena, potentially incurring similar scanning costs if the data format isn''t optimized.', 34, 'm_34_2', 1, NULL, NULL),
  ('mock_32_all_1775005113845', 'A retail company stores daily sales data in an Amazon S3 bucket in Apache Parquet format. Business users require interactive dashboards and reports to monitor sales trends and product performance. The data engineering team aims to provide this capability with the LEAST operational overhead. Which AWS service should they use?', '["Set up Amazon Athena to query the Parquet data and connect Amazon QuickSight for visualization.","Deploy an Amazon Redshift cluster and load the data for reporting.","Use Amazon EMR Studio notebooks to generate reports and dashboards.","Develop custom web applications on Amazon EC2 to visualize data from S3."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the least operational overhead. Amazon Athena is a serverless query service that allows running SQL queries directly on data in Amazon S3 without managing any infrastructure. Amazon QuickSight is a serverless business intelligence service that can directly connect to Athena, providing interactive dashboards and reports with minimal setup and maintenance. This combination offers a fully managed, scalable, and cost-effective solution for BI.
Option B (incorrect) involves deploying and managing an Amazon Redshift cluster, which introduces significant operational overhead compared to a serverless solution, even though it''s a powerful data warehouse. It does not meet the ''LEAST operational overhead'' constraint.
Option C (incorrect) uses Amazon EMR Studio, which is primarily for interactive data exploration and Spark-based development. While it can generate reports, it''s not a dedicated BI visualization tool and requires more operational effort for managing the EMR clusters and notebooks compared to QuickSight.
Option D (incorrect) would require significant development and maintenance effort for custom web applications, including managing Amazon EC2 instances, which directly contradicts the ''LEAST operational overhead'' requirement.', 34, 'm_34_2', 2, NULL, NULL),
  ('mock_32_all_1775005113845', 'A financial institution processes hundreds of terabytes of historical transaction data for complex analytical queries involving multiple JOINs and aggregations. These queries run on a predictable, daily schedule and require optimal performance. The data is currently stored in Amazon S3. Which AWS service is BEST suited for this workload to ensure OPTIMAL performance for complex queries?', '["Utilize Amazon Athena to query the data directly from Amazon S3.","Load the data into an Amazon Redshift cluster, optimizing with distribution and sort keys.","Process the data using Amazon EMR Studio with Apache Spark.","Create dashboards in Amazon QuickSight connected to the S3 data."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the best solution for optimal performance on complex, large-scale analytical queries with predictable workloads. Amazon Redshift is a fully managed, petabyte-scale data warehouse service specifically designed for high-performance analytical queries. Optimizing tables with appropriate distribution and sort keys significantly enhances query speed for complex operations like JOINs and aggregations.
Option A (incorrect) Amazon Athena is serverless and excellent for ad-hoc queries, but for hundreds of terabytes and highly complex, predictable queries requiring optimal performance, a dedicated data warehouse like Redshift typically offers superior performance and cost predictability, especially with careful optimization.
Option C (incorrect) Amazon EMR Studio with Apache Spark is highly flexible for data processing and exploration, but for a dedicated data warehousing workload with predictable, performance-critical SQL queries, Amazon Redshift is purpose-built and generally more optimized for this specific use case.
Option D (incorrect) Amazon QuickSight is a business intelligence service for visualization and dashboards. It is not a data warehousing solution for processing and querying raw data, but rather a tool to consume data from services like Redshift or Athena.', 34, 'm_34_2', 3, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data science team needs to perform interactive data exploration and develop Spark-based ETL scripts on petabytes of data stored in Amazon S3. They require a collaborative environment that supports multiple users working on the same datasets and notebooks. Which AWS service provides the BEST collaborative environment for Spark-based exploration?', '["Use Amazon Athena for interactive SQL queries on the S3 data.","Configure AWS Batch jobs to run Spark scripts on a schedule.","Utilize Amazon EMR Studio notebooks for interactive Spark development.","Create dashboards in Amazon QuickSight to visualize data."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best choice for a collaborative environment for Spark-based exploration. Amazon EMR Studio provides a fully managed, interactive development environment (IDE) for data scientists and data engineers to develop, debug, and run Apache Spark, Apache Hive, and Presto applications. It integrates with Jupyter notebooks and allows multiple users to collaborate on the same notebooks and underlying EMR clusters, making it ideal for data science teams.
Option A (incorrect) Amazon Athena is a serverless query service for SQL queries. It does not support Spark or provide an interactive notebook environment for data science teams.
Option B (incorrect) AWS Batch is designed for running large-scale batch computing workloads. While it can run Spark jobs, it''s not an interactive or collaborative environment for development and exploration.
Option D (incorrect) Amazon QuickSight is a business intelligence service for creating visualizations and dashboards. It is not designed for interactive data exploration or Spark-based ETL script development.', 34, 'm_34_2', 4, NULL, NULL),
  ('mock_32_all_1775005113845', 'A marketing team needs to analyze customer behavior data stored in an Amazon S3 bucket, which is currently in JSON format. They require a serverless solution to query this data using standard SQL without managing any infrastructure, while also optimizing for query performance and cost. Which solution meets these requirements with LEAST operational overhead?', '["Convert the JSON data to Apache Parquet format, partition it appropriately, and query using Amazon Athena.","Load the JSON data into an Amazon Redshift cluster and run SQL queries.","Set up an Amazon EMR Studio notebook to process and query the JSON data with Spark SQL.","Use AWS Batch to run a custom script that converts JSON to a database format and loads it into Amazon RDS."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) offers the least operational overhead and is cost-effective for querying. Amazon Athena is a serverless query service that allows running standard SQL queries directly on data in Amazon S3. Converting JSON to Apache Parquet, a columnar and compressed format, and partitioning the data, significantly reduces the amount of data scanned by Athena, leading to lower costs and improved query performance. This avoids the anti-pattern of querying unoptimized data formats.
Option B (incorrect) involves deploying and managing an Amazon Redshift cluster, which introduces operational overhead and higher costs compared to a serverless Athena solution for ad-hoc queries.
Option C (incorrect) uses Amazon EMR Studio, which provides a powerful environment for Spark SQL. However, it requires managing EMR clusters and is more complex than serverless Athena for simple SQL querying, thus increasing operational overhead.
Option D (incorrect) involves AWS Batch and Amazon RDS. AWS Batch is for batch computing, not interactive SQL querying, and Amazon RDS is a relational database service, which would require managing database instances and is not serverless for data lake querying.', 34, 'm_34_2', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_34_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A media company receives new video files (up to 10 GB each) in an Amazon S3 bucket. Each file needs to trigger an encoding process using a custom application running on Amazon EC2 instances. The company requires the LOWEST latency for initiating this processing. Which architecture should be implemented?', '["Configure Amazon S3 event notifications to send messages to an Amazon SQS queue, which an AWS Lambda function then processes to start the EC2 encoding.","Deploy an Amazon EC2 instance with a custom script that continuously polls the Amazon S3 bucket for new files.","Set up an AWS Glue job with a scheduled trigger to check for new files every 5 minutes and initiate encoding.","Use AWS Batch to periodically scan the S3 bucket for new files and submit encoding jobs."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the lowest latency for initiating processing. Amazon S3 event notifications deliver near real-time notifications when objects are created. Sending these notifications to an Amazon SQS queue ensures durability and decoupling, while an AWS Lambda function can immediately process the SQS message to trigger the EC2 encoding process. This is a classic event-driven pattern.
Option B (incorrect) represents an anti-pattern ([ap-3.1-001]) of polling Amazon S3 for new files. Polling introduces latency because new files are only detected at intervals, and it incurs unnecessary compute costs for the polling instance.
Option C (incorrect) uses an AWS Glue job with a scheduled trigger. This approach is not suitable for low-latency, immediate processing as it runs on a predefined schedule, introducing significant delays between file arrival and processing initiation.
Option D (incorrect) uses AWS Batch to periodically scan the S3 bucket. This also involves polling and is not an event-driven, low-latency solution. AWS Batch is excellent for large-scale batch processing but not for immediate, event-driven triggers.', 34, 'm_34_1', 6, NULL, NULL),
  ('mock_32_all_1775005113845', 'A pharmaceutical company needs to process large genomics datasets (terabytes) nightly. The processing involves complex, long-running computational jobs that can be parallelized across many compute instances. The company seeks the MOST scalable and cost-effective solution for these large-scale batch compute workloads. Which AWS service should they choose?', '["Use AWS Lambda functions to execute the computational jobs.","Leverage AWS Batch to manage and run the parallelized jobs.","Set up an Amazon EMR Studio notebook to run the processing scripts.","Create an AWS Glue ETL job to handle the data processing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most scalable and cost-effective for large-scale batch compute workloads. AWS Batch dynamically provisions the optimal quantity and type of compute resources based on the volume and resource requirements of the submitted jobs. It handles job queuing, scheduling, and execution across a fleet of Amazon EC2 instances, making it ideal for complex, parallelizable, and long-running computational tasks.
Option A (incorrect) AWS Lambda functions have execution duration limits (currently 15 minutes) and are not suitable for long-running, complex computational jobs that can take hours or require significant memory/CPU resources.
Option C (incorrect) Amazon EMR Studio notebooks are designed for interactive data exploration and Spark-based development. While EMR clusters can run batch jobs, AWS Batch is specifically optimized for managing generic batch compute workloads, often providing a more cost-effective and simpler operational model for non-Spark specific batch tasks.
Option D (incorrect) AWS Glue ETL jobs are primarily designed for extract, transform, and load operations on structured and semi-structured data. While they can perform complex transformations, AWS Batch is generally more suitable for generic, compute-intensive scientific workloads that require custom binaries or specific compute environments beyond typical ETL.', 34, 'm_34_1', 7, NULL, NULL),
  ('mock_32_all_1775005113845', 'An IoT company collects sensor data in Amazon S3 hourly. They need to run an ETL job every hour to transform this data, enrich it, and load it into a data warehouse. The solution must be RELIABLE and provide automated hourly ETL execution with minimal operational overhead. Which approach meets these requirements?', '["Configure Amazon S3 event notifications to trigger an AWS Lambda function that starts the ETL process.","Deploy an Amazon EC2 instance with a custom script to poll the S3 bucket hourly and run the ETL.","Set up an AWS Glue ETL job with a scheduled trigger to run every hour.","Use AWS Batch to run a custom ETL script on a recurring hourly schedule."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most reliable and automated solution for scheduled hourly ETL with minimal operational overhead. AWS Glue is a serverless ETL service that fully manages the underlying infrastructure. A scheduled trigger allows for precise hourly execution of the ETL job without requiring any server management. This is a standard pattern for recurring ETL tasks.
Option A (incorrect) Amazon S3 event notifications are ideal for immediate, event-driven processing. For a strictly hourly schedule, a scheduled trigger is more appropriate and simpler than orchestrating event notifications for a fixed interval.
Option B (incorrect) represents an anti-pattern ([ap-3.1-001]) of polling Amazon S3 with a custom script on an EC2 instance. This introduces significant operational overhead for managing the EC2 instance, patching, and ensuring script reliability, and is less efficient than a serverless scheduled job.
Option D (incorrect) AWS Batch is suitable for large-scale batch compute, but for standard ETL operations, AWS Glue is purpose-built, serverless, and often more cost-effective and simpler to manage for recurring data transformations.', 34, 'm_34_1', 8, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data analytics team needs to process incoming CSV files in an Amazon S3 bucket immediately after they are uploaded. The processing involves invoking a Python script to validate and transform the data, then storing it back into S3 in Parquet format. The team requires the LEAST operational overhead for this event-driven data transformation. Which solution should they implement?', '["Configure Amazon S3 event notifications to invoke an AWS Lambda function that executes the Python script.","Set up an AWS Glue job with a custom script and a scheduled trigger to run every 15 minutes.","Deploy an Amazon EC2 instance to continuously poll the S3 bucket for new files and run the script.","Use AWS Batch to run the Python script on a daily schedule, processing all new files."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the least operational overhead for event-driven data transformation. Amazon S3 event notifications can directly invoke an AWS Lambda function whenever a new object is created. AWS Lambda is a serverless compute service, meaning there are no servers to provision or manage, and it scales automatically. This setup provides immediate processing with minimal operational effort.
Option B (incorrect) uses an AWS Glue job with a scheduled trigger. This introduces latency as it runs on a schedule, not immediately upon file upload, and has more overhead than a simple Lambda function for a direct event-driven task.
Option C (incorrect) represents an anti-pattern ([ap-3.1-001]) of polling Amazon S3. Deploying and managing an Amazon EC2 instance for continuous polling introduces significant operational overhead, higher costs, and potential latency compared to an event-driven, serverless approach.
Option D (incorrect) uses AWS Batch on a daily schedule. This is not suitable for immediate, event-driven processing and would introduce significant delays in data transformation.', 34, 'm_34_1', 9, NULL, NULL),
  ('mock_32_all_1775005113845', 'A research institution frequently uploads large scientific datasets (multiple gigabytes) to an Amazon S3 bucket. They need to automatically initiate a data validation and preprocessing workflow as soon as a new dataset arrives. This workflow involves several steps, including data parsing, schema validation, and normalization, which can take up to an hour. Which solution provides AUTOMATED and reliable workflow initiation triggered by new data arrival?', '["Configure Amazon S3 event notifications to an Amazon SQS queue, which an AWS Lambda function processes to trigger an AWS Glue job.","Configure an AWS Glue job with a scheduled trigger to run every 15 minutes to check for new files.","Deploy an Amazon EC2 instance with a custom script to poll the S3 bucket every 5 minutes and initiate processing.","Use AWS Batch to run a single large job that polls S3 and processes files on a fixed interval."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides automated and reliable workflow initiation. Amazon S3 event notifications immediately send a message to an Amazon SQS queue upon new file arrival. An AWS Lambda function can then be triggered by the SQS message to initiate a longer-running AWS Glue job, which is suitable for multi-step data validation and preprocessing workflows that can take up to an hour. This leverages event-driven patterns for immediate response and AWS Glue for robust ETL.
Option B (incorrect) uses a scheduled AWS Glue job, which introduces latency as it only runs at fixed intervals, not immediately upon file arrival. This is a polling-like behavior, not truly event-driven.
Option C (incorrect) represents an anti-pattern ([ap-3.1-001]) of polling Amazon S3. Deploying and managing an Amazon EC2 instance for polling is operationally intensive, introduces latency, and is less reliable than a fully managed event-driven architecture.
Option D (incorrect) uses AWS Batch to poll S3. This also introduces polling latency and is not an event-driven solution for immediate processing upon file arrival.', 34, 'm_34_1', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_34_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A financial services company processes transactional data daily using AWS Glue ETL jobs. They need to ensure that specific columns, like `transaction_amount` and `customer_id`, always contain valid, non-null values before the data is used for reporting. Which AWS service and method would be the most effective for implementing these data quality checks with minimal development effort?', '["Write custom Python scripts within the existing AWS Glue ETL job to perform validation.","Implement AWS Glue Data Quality rules directly within the existing AWS Glue ETL job.","Use Amazon CloudWatch alarms to monitor AWS Glue job logs for validation errors.","Manually inspect data samples after each AWS Glue job run to identify quality issues."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective for implementing automated data quality checks with minimal development effort. AWS Glue Data Quality allows you to define data quality rules (e.g., `is not null`, `is unique`, `is in range`) directly within your AWS Glue ETL jobs. It provides a managed way to evaluate data quality, generate scores, and take actions based on rule outcomes, significantly reducing the need for custom coding.
Option A (incorrect) involves writing custom Python scripts. While feasible, this requires more development effort, testing, and maintenance compared to using the built-in capabilities of AWS Glue Data Quality, which is designed for this purpose.
Option C (incorrect) uses Amazon CloudWatch alarms to monitor logs. This is a reactive approach; it can alert you to errors *after* they occur but doesn''t proactively validate data quality during processing or provide detailed data quality scores. It''s for monitoring, not direct quality enforcement.
Option D (incorrect) involves manual inspection, which is not automated, highly inefficient, and prone to human error. It completely fails to meet the requirement for automated data quality checks.', 34, 'm_34_4', 11, NULL, NULL),
  ('mock_32_all_1775005113845', 'A healthcare provider stores patient records in an Amazon S3 data lake. They need to continuously monitor the consistency of patient IDs across different datasets and identify any records with invalid date formats in the `admission_date` field. Which solution provides PROACTIVE and continuous data quality monitoring for their data lake content?', '["Use Amazon Athena to periodically query the data and identify anomalies.","Define and run data quality rules using AWS Glue Data Quality on the Amazon S3 datasets.","Implement custom AWS Lambda functions to scan S3 files for quality issues.","Configure Amazon CloudWatch metrics to track S3 object counts and sizes."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides proactive and continuous data quality monitoring. AWS Glue Data Quality is specifically designed to define, monitor, and enforce data quality rules across data lakes and data pipelines. It can run directly on data in Amazon S3, allowing for continuous assessment of consistency, validity, and format, and can generate detailed data quality scores and reports.
Option A (incorrect) involves using Amazon Athena for periodic queries. While Athena can identify issues, this is a manual or semi-manual approach that is not continuous or proactive in the same way as a dedicated data quality service. It requires explicit query development and execution.
Option C (incorrect) involves implementing custom AWS Lambda functions. This approach would require significant development, testing, and maintenance effort to build a robust data quality solution, which is less efficient than using a managed service like AWS Glue Data Quality.
Option D (incorrect) uses Amazon CloudWatch metrics to track S3 object counts and sizes. This monitors storage metadata but does not provide insights into the actual content or quality of the data within the S3 objects.', 34, 'm_34_4', 12, NULL, NULL),
  ('mock_32_all_1775005113845', 'An e-commerce company uses AWS Glue ETL jobs to prepare product catalog data for their website. They need to ensure that the `product_price` column is always a positive number and that the `product_category` column matches a predefined list of valid categories. Which solution allows them to ENFORCE data quality rules directly within the ETL pipeline?', '["Integrate AWS Glue Data Quality rules into the AWS Glue ETL job to validate data during processing.","Develop custom validation logic in Python scripts executed by an Amazon EMR Studio notebook.","Periodically export data to Amazon Redshift and run SQL queries to check data quality.","Manually review data samples in Amazon QuickSight dashboards for anomalies."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most direct and efficient way to enforce data quality rules within an ETL pipeline. AWS Glue Data Quality is designed to be integrated directly into AWS Glue ETL jobs. This allows for real-time validation of data as it flows through the pipeline, ensuring that data quality rules are applied before the data is consumed by downstream systems. It provides a managed and scalable approach to data quality enforcement.
Option B (incorrect) involves developing custom validation logic in Python scripts within an Amazon EMR Studio notebook. This approach requires more development and operational overhead compared to using the native AWS Glue Data Quality features, and it''s not as tightly integrated into the Glue ETL process.
Option C (incorrect) involves exporting data to Amazon Redshift and running SQL queries. This is a reactive approach that checks data quality after the ETL process is complete, rather than enforcing it inline, and adds additional data movement and cost.
Option D (incorrect) involves manual review using Amazon QuickSight. This is a reactive, manual, and non-scalable approach that does not enforce data quality rules automatically within the pipeline.', 34, 'm_34_4', 13, NULL, NULL),
  ('mock_32_all_1775005113845', 'A logistics company ingests shipment tracking data into an Amazon S3 data lake. They need to identify and flag records where the `delivery_status` field is missing or contains unexpected values, and where `shipment_id` is not unique. The company requires a COMPREHENSIVE data quality assessment and reporting solution on their data lake content. Which AWS service should they utilize?', '["Create Amazon CloudWatch alarms to detect high error rates in AWS Glue job logs.","Utilize AWS Glue Data Quality to define data quality rules and generate data quality scores and reports.","Use Amazon Athena to run ad-hoc queries for data validation.","Implement a custom AWS Batch job to run data profiling scripts."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution for comprehensive data quality assessment and reporting. AWS Glue Data Quality allows defining a wide range of data quality rules (e.g., completeness, uniqueness, validity) and executing them against data in Amazon S3. It then generates data quality scores and detailed reports, providing a holistic view of data quality across the data lake, which is essential for identifying and flagging issues like missing or unexpected values and non-unique IDs.
Option A (incorrect) uses Amazon CloudWatch alarms, which are for monitoring operational metrics and logs. While they can alert on job failures, they do not provide detailed insights into the content-level data quality or generate comprehensive data quality reports.
Option C (incorrect) involves using Amazon Athena for ad-hoc queries. This is a manual and reactive approach for specific checks, not a comprehensive, automated data quality assessment and reporting solution.
Option D (incorrect) involves implementing a custom AWS Batch job. While technically possible to run data profiling scripts, this approach requires significant development and maintenance effort to build a solution that AWS Glue Data Quality provides as a managed service, increasing operational overhead.', 34, 'm_34_4', 14, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data team processes customer feedback data from various sources into an Amazon S3 data lake using AWS Glue. They need to ensure that the `feedback_text` column is never empty and that the `rating` column is within a specific numerical range (1-5). The team requires AUTOMATED and scalable data validation for data lake ingestion. Which solution should they implement?', '["Develop and maintain custom Python scripts within AWS Lambda to perform data validation on S3 events.","Use Amazon QuickSight to visualize data quality metrics from aggregated reports.","Configure AWS Glue Data Quality to apply validation rules on the incoming data as part of the AWS Glue ETL process.","Set up Amazon CloudWatch metrics to count S3 objects and trigger alerts if counts are too low."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides automated and scalable data validation for data lake ingestion. AWS Glue Data Quality is designed to integrate directly into AWS Glue ETL jobs, allowing you to define and apply validation rules (e.g., `is not null`, `is in range`) as data is being processed. This ensures that data quality is enforced at the point of ingestion and transformation, with minimal operational overhead as it''s a managed service feature.
Option A (incorrect) involves developing and maintaining custom Python scripts within AWS Lambda. While Lambda can be event-driven, building a comprehensive and scalable data validation framework from scratch requires significant development and maintenance effort, which is less efficient than using a dedicated service like AWS Glue Data Quality.
Option B (incorrect) uses Amazon QuickSight for visualization. This is a reactive approach, visualizing quality metrics after they''ve been generated, rather than proactively validating data during ingestion. It doesn''t enforce quality rules directly.
Option D (incorrect) uses Amazon CloudWatch metrics to count S3 objects. This only monitors the volume of data, not its content or quality. It cannot validate specific column values or ranges.', 34, 'm_34_4', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_34_3
