INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A data pipeline processes daily incremental updates from a source system into an Amazon S3 data lake using an AWS Glue ETL job. The team wants to ensure that only new or changed data is processed in each run to optimize costs and processing time. Which feature should be enabled for the AWS Glue ETL job to achieve the MOST efficient incremental data processing?', '["Enable AWS Glue job bookmarks for the AWS Glue ETL job.","Implement custom logic within the Glue job to track processed files in a DynamoDB table.","Schedule the Glue job to run on a larger instance type to process all data faster.","Use Amazon CloudWatch to monitor Glue job run times and manually adjust parameters."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient way to achieve incremental data processing. AWS Glue job bookmarks track previously processed data, allowing AWS Glue ETL jobs to process only new or changed data from the source on subsequent runs. This significantly optimizes costs and processing time by avoiding reprocessing of the entire dataset, directly addressing the anti-pattern ([ap-3.3-001]) of not enabling job bookmarks for incremental ETL.
Option B (incorrect) involves implementing custom logic to track processed files. This approach requires significant development effort, is prone to errors, and increases operational overhead compared to using the built-in AWS Glue job bookmarks feature.
Option C (incorrect) suggests scheduling the Glue job on a larger instance type. This would increase costs and is an inefficient way to handle incremental processing, as it still processes the entire dataset, just faster, rather than only processing new data.
Option D (incorrect) uses Amazon CloudWatch for monitoring. While monitoring is important, it is a reactive measure and does not directly optimize the incremental processing logic of the Glue job itself.', 34, 'm_34_3', 16, NULL, NULL),
  ('mock_32_all_1775005113845', 'An AWS Glue ETL job runs every night to transform customer data. The data engineering team needs to be immediately notified if the job fails or takes longer than 30 minutes to complete. Which solution provides PROACTIVE alerting for pipeline failures and performance issues?', '["Regularly check AWS Glue job history in the AWS Management Console.","Configure Amazon CloudWatch alarms on AWS Glue job metrics for `FailedRuns` and `DPUHour` to send notifications via Amazon SNS.","Implement custom logging within the Glue job and analyze logs with Amazon CloudWatch Logs Insights daily.","Use AWS Batch to monitor Glue job status and send alerts."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides proactive and immediate alerting. Amazon CloudWatch automatically collects metrics for AWS Glue jobs, including `FailedRuns` and `DPUHour` (which can indicate long-running jobs). Configuring CloudWatch alarms on these metrics to trigger an Amazon SNS topic ensures that the team receives immediate notifications via email, SMS, or other subscribed endpoints when a job fails or exceeds its expected duration.
Option A (incorrect) involves manually checking the AWS Management Console, which is a reactive and non-scalable approach that does not provide immediate notification.
Option C (incorrect) involves custom logging and daily analysis with Amazon CloudWatch Logs Insights. This is a reactive approach for post-mortem analysis and does not provide immediate, proactive alerts for ongoing job failures or performance issues.
Option D (incorrect) uses AWS Batch. AWS Batch is a compute service for running batch jobs, not a monitoring service for AWS Glue jobs. It is not designed to monitor the status or performance of other AWS services.', 34, 'm_34_3', 17, NULL, NULL),
  ('mock_32_all_1775005113845', 'A streaming data pipeline uses Amazon Kinesis Data Streams to ingest real-time data, which is then processed by AWS Lambda and stored in Amazon S3. The operations team needs to monitor the data ingestion rate and identify any bottlenecks in the Kinesis stream. Which solution offers REAL-TIME monitoring of Kinesis stream performance?', '["Use Amazon EMR Studio to analyze Kinesis data logs for performance issues.","Implement custom AWS Glue jobs to periodically analyze Kinesis stream metrics.","Create Amazon CloudWatch dashboards and alarms based on Amazon Kinesis Data Streams metrics such as `IncomingBytes` and `ReadProvisionedThroughputExceeded`.","Manually inspect Kinesis stream shards in the AWS Management Console at regular intervals."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides real-time monitoring of Amazon Kinesis Data Streams performance. Amazon CloudWatch automatically collects detailed metrics for Kinesis Data Streams, including `IncomingBytes` (ingestion rate), `IncomingRecords`, `ReadProvisionedThroughputExceeded`, and `WriteProvisionedThroughputExceeded`. Creating CloudWatch dashboards allows for real-time visualization, and setting up alarms on these metrics ensures immediate notification of potential bottlenecks or performance issues.
Option A (incorrect) uses Amazon EMR Studio. EMR Studio is for interactive data exploration and Spark-based processing, not for real-time monitoring of Kinesis stream operational metrics.
Option B (incorrect) involves custom AWS Glue jobs. AWS Glue is an ETL service and running periodic jobs to analyze metrics would not provide real-time insights into a streaming pipeline. It introduces latency and is not designed for continuous operational monitoring.
Option D (incorrect) involves manual inspection of Kinesis stream shards. This is a reactive, non-scalable, and inefficient approach that does not provide continuous or real-time monitoring capabilities.', 34, 'm_34_3', 18, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data lake architecture uses AWS Glue ETL jobs to process data. The data engineering team wants to ensure that the data quality rules defined using AWS Glue Data Quality are consistently applied and that any violations are reported. Which solution enables EFFECTIVE monitoring and reporting on data quality rule execution?', '["Manually review AWS Glue Data Quality reports after each job run.","Use Amazon QuickSight to create dashboards for raw data and visually identify quality issues.","Configure Amazon CloudWatch to monitor AWS Glue Data Quality metrics and generate alerts for rule violations.","Implement custom AWS Lambda functions to parse Glue job logs for data quality errors."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides effective monitoring and reporting for AWS Glue Data Quality rule execution. AWS Glue Data Quality integrates with Amazon CloudWatch, emitting metrics related to data quality rule evaluations, such as the number of passed or failed rules. Configuring CloudWatch alarms on these metrics allows for automated alerting on rule violations, and CloudWatch dashboards can visualize data quality trends and scores over time, providing comprehensive monitoring.
Option A (incorrect) involves manual review of reports. This is a reactive and non-scalable approach that does not provide immediate or automated monitoring and alerting capabilities.
Option B (incorrect) uses Amazon QuickSight to visualize raw data. While QuickSight is for BI, it''s not designed to directly monitor the execution and results of data quality rules. It would require the data quality metrics to be pre-processed and made available for visualization.
Option D (incorrect) involves implementing custom AWS Lambda functions to parse logs. This approach requires significant development and maintenance effort to extract and interpret data quality information from logs, which is less efficient than using the native CloudWatch integration provided by AWS Glue Data Quality.', 34, 'm_34_3', 19, NULL, NULL),
  ('mock_32_all_1775005113845', 'A company uses Amazon EMR clusters for large-scale data processing. They need to track the utilization of their EMR clusters, including CPU utilization and memory usage, to optimize resource allocation and identify potential performance bottlenecks. Which AWS service provides COMPREHENSIVE monitoring of Amazon EMR cluster resources?', '["Log into the Amazon EMR Studio interface to check cluster status manually.","Use AWS Batch to run scripts that collect EMR metrics.","Utilize Amazon CloudWatch to collect and visualize metrics for Amazon EMR clusters and set up alarms for high resource utilization.","Configure AWS Glue job bookmarks to track EMR resource usage."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides comprehensive monitoring of Amazon EMR cluster resources. Amazon CloudWatch automatically collects a wide range of metrics for Amazon EMR clusters, including CPU utilization, memory usage, disk I/O, and network activity. These metrics can be visualized in CloudWatch dashboards, and alarms can be configured to notify operations teams of high resource utilization or other performance bottlenecks, enabling proactive management and optimization.
Option A (incorrect) involves manually logging into Amazon EMR Studio. This is a reactive and non-scalable approach that does not provide continuous, automated monitoring or alerting capabilities.
Option B (incorrect) uses AWS Batch. AWS Batch is a compute service for running batch jobs, not a dedicated monitoring service. While it could theoretically run scripts to collect metrics, it''s an inefficient and overly complex way to monitor EMR clusters compared to the native integration with CloudWatch.
Option D (incorrect) involves AWS Glue job bookmarks. Job bookmarks are a feature of AWS Glue ETL jobs used for incremental processing, not for monitoring the resource utilization of Amazon EMR clusters. These two concepts are unrelated.', 34, 'm_34_3', 20, NULL, NULL);

