INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A data analytics company needs to grant a third-party partner secure, read-only access to a specific Amazon S3 bucket containing aggregated, non-PII data. The solution must ensure least privilege and be easily revocable, without requiring the partner to manage AWS credentials directly. Which approach meets these requirements with the LEAST administrative overhead?', '["Create an IAM role in the partner''s AWS account and configure an S3 bucket policy in the analytics company''s account to grant access to that role.","Generate IAM user access keys for the partner in the analytics company''s account and share them securely.","Configure the S3 bucket policy to allow public read access to the specific objects the partner needs.","Set up AWS PrivateLink endpoints for the S3 bucket, allowing the partner to connect securely from their VPC."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most secure and manageable approach for cross-account access. The analytics company''s S3 bucket policy grants permissions to an IAM role in the partner''s account, allowing the partner to assume the role and access the data without managing separate credentials. This adheres to the principle of least privilege and is easily revocable by modifying the bucket policy. Option B (incorrect) involves sharing long-lived credentials, which is a security risk and increases administrative overhead for key rotation and management. Option C (incorrect) grants public access, violating the security and least privilege requirements. Option D (incorrect) provides private connectivity to S3 but does not manage access control to the data itself; it''s a networking solution, not an authorization mechanism for cross-account data access.', 35, 'm_35_1', 1, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data engineering team uses AWS Glue ETL jobs to process sensitive customer data stored in Amazon S3. The team needs to ensure that Glue jobs can only access the specific S3 buckets and prefixes required for their operation, adhering to the principle of least privilege. What is the most secure and operationally efficient way to configure access for these AWS Glue jobs?', '["Embed S3 access keys directly into the AWS Glue job scripts for authentication.","Create an IAM role with specific S3 bucket permissions and assign it as the execution role for the AWS Glue job.","Configure S3 bucket policies to allow access from all AWS Glue service principals in the region.","Grant full AmazonS3FullAccess permissions to the default AWS Glue service role."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the recommended and most secure approach. By creating an IAM role with specific, least-privilege S3 bucket permissions and assigning it as the AWS Glue job''s execution role, you ensure that the job only has the necessary access. This eliminates the need to manage credentials within the job code and integrates seamlessly with AWS Glue. Option A (incorrect) is a severe security anti-pattern, as embedding credentials in code is insecure and difficult to manage. Option C (incorrect) grants overly broad access to all AWS Glue jobs, violating the principle of least privilege. Option D (incorrect) also violates the principle of least privilege by granting full S3 access, which is unnecessary and poses a security risk.', 35, 'm_35_1', 2, NULL, NULL),
  ('mock_32_all_1775005113845', 'A company has an Amazon Redshift cluster that needs to query external data stored in Amazon S3 using Amazon Redshift Spectrum. The data in S3 is organized into various datasets, and the Redshift cluster requires specific read-only access to these datasets. How should the Redshift cluster be securely authorized to access the S3 data for Redshift Spectrum queries?', '["Store S3 access credentials directly within the Redshift cluster configuration.","Create an IAM user with S3 read permissions and configure Redshift to use these credentials.","Associate an IAM role with the Redshift cluster and grant that role the necessary S3 read permissions.","Modify the S3 bucket policies to allow public read access to the Redshift cluster''s IP address range."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the secure and recommended method. Associating an IAM role with the Amazon Redshift cluster allows Redshift Spectrum to assume this role and access S3 data based on the permissions granted to the role. This leverages AWS''s robust IAM framework for secure, role-based access without managing credentials. Option A (incorrect) and Option B (incorrect) involve storing or managing credentials directly, which is a security anti-pattern and increases operational overhead. Option D (incorrect) would grant public access to the S3 data, which is a major security vulnerability and does not provide fine-grained control.', 35, 'm_35_1', 3, NULL, NULL),
  ('mock_32_all_1775005113845', 'A financial services company needs to securely ingest data from an external partner''s Amazon S3 bucket into their own AWS account. The partner wants to grant access to a specific folder within their S3 bucket, ensuring that only the company''s designated ingestion service can read the data. Which mechanism should the partner use to grant this granular, cross-account access?', '["Provide the company with an IAM user''s access keys from the partner''s account that have S3 read permissions.","Configure an S3 bucket policy on the partner''s bucket to allow access to an IAM role in the company''s account.","Create an AWS PrivateLink endpoint for the partner''s S3 bucket and share it with the company.","Grant full public read access to the specific S3 folder from the partner''s account."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most secure and granular method for cross-account S3 access. The partner''s S3 bucket policy can be configured to grant permissions to a specific IAM role in the financial company''s account. This allows the company''s ingestion service to assume that role and access only the designated S3 folder, adhering to least privilege without sharing credentials. Option A (incorrect) involves sharing long-lived credentials, which is a security risk. Option C (incorrect) provides private network connectivity but does not manage access control to the data itself. Option D (incorrect) grants public access, which is a severe security vulnerability and violates the requirement for secure, granular access.', 35, 'm_35_1', 4, NULL, NULL);

