INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A large enterprise has a data lake built on Amazon S3 and AWS Glue Data Catalog, containing various datasets with different sensitivity levels. Data analysts from different departments require access to specific tables and columns within this data lake. The enterprise needs a solution that provides fine-grained access control with the LEAST operational overhead for managing permissions. Which AWS service should be used?', '["AWS Lake Formation.","Amazon S3 bucket policies alone.","Creating separate Amazon S3 buckets for each department and sensitivity level.","Managing IAM policies attached directly to individual data analyst IAM users."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is designed for this exact scenario. AWS Lake Formation provides a centralized way to manage fine-grained access control (table-level, column-level, row-level) to data in an S3-based data lake, integrated with the AWS Glue Data Catalog. It significantly reduces operational overhead compared to manual approaches. Option B (incorrect) represents anti-pattern [ap-4.1-001]; S3 bucket policies grant broad bucket-level access and do not support fine-grained table or column-level permissions for data lake resources. Option C (incorrect) would lead to high operational overhead due to data duplication and managing many separate buckets. Option D (incorrect) would also result in high operational overhead and complexity, as IAM policies attached to individual users are difficult to scale and manage for fine-grained data access.', 35, 'm_35_2', 5, NULL, NULL),
  ('mock_32_all_1775005113845', 'A research institution uses Amazon EMR clusters to process sensitive genomic data stored in an AWS Lake Formation-managed data lake. The institution needs to ensure that EMR jobs can only access specific tables and columns that their assigned IAM roles are authorized for, without manually configuring S3 permissions. How should this authorization be enforced for EMR clusters?', '["Configure S3 bucket policies on the underlying S3 data to grant access to the EMR cluster''s IP address.","Ensure the EMR cluster''s instance profile has an IAM role registered with AWS Lake Formation, with appropriate data permissions.","Store database credentials directly on the EMR cluster nodes for accessing Lake Formation resources.","Grant full AmazonS3FullAccess to the EMR cluster''s instance profile and rely on application-level filtering."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the proper way to integrate Amazon EMR with AWS Lake Formation. By registering the EMR cluster''s IAM role (via its instance profile) with Lake Formation, Lake Formation can enforce its centralized, fine-grained permissions on the data accessed by EMR. This provides secure and integrated authorization. Option A (incorrect) bypasses Lake Formation''s governance model and is not a scalable or secure way to manage data lake access. Option C (incorrect) is a security anti-pattern as it involves storing credentials directly on compute nodes. Option D (incorrect) grants overly broad S3 access, violating the principle of least privilege and undermining Lake Formation''s purpose.', 35, 'm_35_2', 6, NULL, NULL),
  ('mock_32_all_1775005113845', 'A healthcare provider stores patient data in an Amazon S3-based data lake, cataloged in AWS Glue. Analysts require access to patient demographics, but specific PII columns like ''SocialSecurityNumber'' must be restricted to only authorized compliance officers. The solution must ensure column-level security for queries from Amazon Athena and Amazon Redshift Spectrum. Which AWS service provides this capability with minimal configuration?', '["Implement column-level security using AWS Lake Formation.","Create separate Amazon S3 buckets for each column and manage access via S3 bucket policies.","Use Amazon Redshift database user permissions to restrict column access.","Encrypt sensitive columns in S3 using different AWS KMS keys and manage key access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the purpose-built solution for this requirement. AWS Lake Formation allows you to define fine-grained permissions, including column-level access control, on tables in the AWS Glue Data Catalog. These permissions are enforced for services like Amazon Athena and Amazon Redshift Spectrum, ensuring that only authorized users can query specific sensitive columns. Option B (incorrect) would be highly complex, inefficient, and operationally burdensome to manage. Option C (incorrect) applies to Redshift''s internal tables, not external tables queried via Redshift Spectrum which relies on Lake Formation for external data. Option D (incorrect) provides encryption at rest but does not offer dynamic column-level access control for query results.', 35, 'm_35_2', 7, NULL, NULL),
  ('mock_32_all_1775005113845', 'A media company needs to securely share a curated dataset from its AWS Lake Formation-managed data lake with a marketing agency in a different AWS account. The company wants to grant access to specific tables and views without duplicating data or managing complex cross-account S3 bucket policies. Which feature should the media company leverage for this controlled data sharing?', '["Manually copy the data to a new Amazon S3 bucket in the marketing agency''s account.","Grant full Amazon S3 bucket access to the marketing agency''s AWS account via a bucket policy.","Utilize AWS Lake Formation''s cross-account data sharing capabilities.","Provide the marketing agency with an IAM user and access keys from the media company''s account."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the ideal solution for secure, controlled cross-account data sharing within a data lake. AWS Lake Formation allows you to grant permissions on specific tables, columns, or rows to external AWS accounts without duplicating data or managing complex S3 bucket policies directly. Option A (incorrect) involves data duplication, which is inefficient and increases management overhead. Option B (incorrect) represents anti-pattern [ap-4.1-001] by granting broad S3 bucket access, which is not granular and violates the principle of least privilege. Option D (incorrect) is a security anti-pattern as it involves sharing long-lived credentials, which is insecure and difficult to manage.', 35, 'm_35_2', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_35_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A healthcare startup stores patient records in an Amazon S3 data lake. Due to strict compliance requirements, all data at rest must be encrypted using customer-managed keys, and the encryption key usage must be auditable. The solution should also minimize operational overhead for key management. Which encryption method should be implemented for the S3 data lake?', '["Amazon S3 server-side encryption with AWS KMS customer-managed keys (SSE-KMS).","Amazon S3 server-side encryption with S3-managed keys (SSE-S3).","Client-side encryption where the application encrypts data before uploading to S3 using its own encryption library.","Amazon S3 server-side encryption with customer-provided keys (SSE-C)."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides encryption at rest using customer-managed keys (CMKs) in AWS KMS. This meets the requirement for customer-managed keys and allows for auditing key usage through AWS CloudTrail. AWS KMS also handles key rotation and management, minimizing operational overhead. Option B (incorrect) uses S3-managed keys, which are not customer-managed. Option C (incorrect) requires the application to handle encryption, key management, and key rotation, significantly increasing operational overhead. Option D (incorrect) requires the customer to manage and provide encryption keys for each request, which is also operationally intensive and less suitable for a data lake with auditable key usage.', 35, 'm_35_3', 9, NULL, NULL),
  ('mock_32_all_1775005113845', 'A financial institution stores customer transaction data, including sensitive PII, in an Amazon Redshift data warehouse. Analysts need to query this data for reporting, but PII columns like ''AccountNumber'' and ''CustomerName'' must be masked for most users, while remaining visible to authorized compliance personnel. The solution must ensure compliance with data privacy regulations. Which Redshift feature should be used?', '["Encrypt the entire Amazon Redshift cluster using AWS KMS.","Implement dynamic data masking in Amazon Redshift.","Create separate tables with masked versions of the sensitive columns for general analyst access.","Grant all analysts full access to the unmasked data and rely on application-level filtering."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the requirement for dynamic data masking. Amazon Redshift''s dynamic data masking allows you to define masking rules for sensitive columns based on user roles or groups. This ensures that unauthorized users see masked data (e.g., ''XXXX-XXXX-1234'') while authorized users see the original values, without altering the underlying data. Option A (incorrect) provides encryption at rest but does not mask data during queries. Option C (incorrect) would lead to data duplication, increased storage costs, and significant operational overhead for maintaining masked tables. Option D (incorrect) represents anti-pattern [ap-4.2-001] by exposing unmasked PII to all analysts, which violates data minimization principles and regulatory requirements.', 35, 'm_35_3', 10, NULL, NULL),
  ('mock_32_all_1775005113845', 'A healthcare organization has a large Amazon S3 data lake containing various unstructured and semi-structured data, including potential Protected Health Information (PHI). They need an automated service to continuously discover, classify, and report on sensitive data, such as PHI, within their S3 buckets to ensure compliance. Which AWS service should they use?', '["AWS CloudTrail for S3 data events.","Amazon Macie.","AWS Lake Formation.","Manually review S3 object contents using custom scripts."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for this purpose. Amazon Macie is a data security and data privacy service that uses machine learning and pattern matching to discover, classify, and protect sensitive data in Amazon S3. It can automatically identify PII/PHI and generate findings for compliance reporting. Option A (incorrect) logs API activity but does not analyze the content of S3 objects for sensitive data. Option C (incorrect) is for managing access control and permissions for data lakes, not for discovering sensitive data within objects. Option D (incorrect) is not automated, scalable, or efficient for continuous monitoring of a large data lake.', 35, 'm_35_3', 11, NULL, NULL),
  ('mock_32_all_1775005113845', 'A company processes sensitive financial data using AWS Glue ETL jobs that read from and write to Amazon S3. To meet stringent compliance requirements, all data must be encrypted both at rest and in transit throughout the entire data pipeline. Which combination of configurations ensures end-to-end encryption for this scenario?', '["Configure S3 server-side encryption (SSE-S3) for all buckets and ensure AWS Glue jobs run within a VPC.","Implement client-side encryption within the AWS Glue job code and enable S3 bucket versioning.","Configure S3 server-side encryption (SSE-KMS) for all buckets and enforce TLS for S3 connections via bucket policies and Glue connection properties.","Rely solely on AWS PrivateLink for S3 access and encrypt data using AWS KMS for at-rest encryption."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides end-to-end encryption. SSE-KMS ensures data is encrypted at rest in S3 using customer-managed keys. Enforcing TLS (Transport Layer Security) for S3 connections, either through S3 bucket policies or by configuring AWS Glue connection properties, ensures data is encrypted in transit between AWS Glue and S3. Option A (incorrect) uses SSE-S3 (not customer-managed keys) and running Glue in a VPC secures network isolation but doesn''t explicitly enforce TLS for S3 data transfer. Option B (incorrect) increases operational overhead by requiring custom client-side encryption logic and S3 versioning is for data recovery, not encryption. Option D (incorrect) PrivateLink provides private connectivity, but doesn''t enforce encryption in transit on the data itself; KMS only covers at-rest encryption.', 35, 'm_35_3', 12, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_35_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A security team needs to monitor and audit all data access events (e.g., GetObject, PutObject, DeleteObject) for sensitive customer data stored in an Amazon S3 bucket. These audit logs are crucial for compliance and forensic analysis. Which AWS service and configuration should be used to capture these specific events?', '["AWS CloudTrail configured to log S3 data events.","AWS CloudTrail configured to log S3 management events.","Amazon S3 server access logging.","AWS CloudWatch Logs for S3 bucket metrics."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the precise solution for auditing S3 data access events. AWS CloudTrail, when configured to log data events, captures API calls made on or within the data of an S3 bucket, such as GetObject, PutObject, and DeleteObject. This provides comprehensive audit trails for compliance. Option B (incorrect) captures S3 management events (e.g., CreateBucket, DeleteBucket) but not data access operations. Option C (incorrect) provides server access logs that record requests made to an S3 bucket, but CloudTrail data events offer a more integrated and auditable solution for compliance. Option D (incorrect) provides metrics on S3 usage, not detailed access logs.', 35, 'm_35_4', 13, NULL, NULL),
  ('mock_32_all_1775005113845', 'A compliance officer requires a centralized, immutable audit trail of all API calls made to AWS services within their account for regulatory compliance. The logs must be retained for seven years and easily queryable for security investigations. Which AWS service is primarily responsible for generating these comprehensive audit logs?', '["Amazon CloudWatch Logs for application logs.","AWS CloudTrail.","AWS Audit Manager.","Amazon S3 server access logging."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the primary service for this requirement. AWS CloudTrail records all API calls made to AWS services in an account, providing a comprehensive audit trail for governance, compliance, and operational auditing. CloudTrail logs can be delivered to an Amazon S3 bucket for long-term, immutable storage and can be queried using services like AWS CloudTrail Lake or Amazon Athena. Option A (incorrect) is used for collecting and monitoring application and system logs, not AWS service API calls. Option C (incorrect) helps automate evidence collection for audits but relies on other services like CloudTrail for the raw log data. Option D (incorrect) is specific to S3 object access logs, not all AWS service API calls.', 35, 'm_35_4', 14, NULL, NULL),
  ('mock_32_all_1775005113845', 'A security team frequently needs to investigate unusual activity and potential security incidents by querying historical AWS CloudTrail logs across multiple regions. They require a solution that provides a SQL-like interface for efficient analysis of these logs without needing to manage underlying infrastructure. Which AWS service is best suited for this task?', '["Amazon Athena querying CloudTrail logs in Amazon S3.","AWS CloudTrail Lake.","Amazon OpenSearch Service for log analysis.","AWS CloudWatch Logs Insights."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for this use case. AWS CloudTrail Lake allows you to aggregate, immutably store, and query CloudTrail events using a SQL-like interface, optimized for security investigations and auditing. It eliminates the need to manage underlying data lakes or query engines. Option A (incorrect) is a valid approach but requires setting up and managing an Athena table over CloudTrail logs, which is more operational overhead than CloudTrail Lake. Option C (incorrect) is typically used for real-time operational log analysis and can be complex to set up and manage for historical CloudTrail data. Option D (incorrect) is for querying logs stored in Amazon CloudWatch Logs, not directly CloudTrail logs.', 35, 'm_35_4', 15, NULL, NULL),
  ('mock_32_all_1775005113845', 'A highly regulated organization needs to ensure the integrity and non-repudiation of its AWS CloudTrail logs for compliance purposes. The logs must be stored in a way that prevents any alteration or deletion for a specified retention period. Which Amazon S3 feature, when used with CloudTrail, can meet this requirement?', '["Encrypting the S3 bucket with AWS KMS keys.","Configuring Amazon S3 Object Lock in WORM (Write Once Read Many) mode.","Enabling S3 bucket versioning for the CloudTrail log bucket.","Using S3 Replication to copy logs to another bucket in a different region."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective way to ensure the integrity and immutability of CloudTrail logs. Amazon S3 Object Lock in WORM mode prevents objects from being overwritten or deleted for a fixed amount of time or indefinitely, which is critical for compliance and non-repudiation of audit trails. Option A (incorrect) provides encryption at rest, protecting confidentiality, but does not prevent modification or deletion. Option C (incorrect) keeps multiple versions of an object but still allows deletion of all versions, and it doesn''t prevent overwrites. Option D (incorrect) provides redundancy but doesn''t inherently prevent modification or deletion of the original or replicated logs.', 35, 'm_35_4', 16, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_35_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775005113845', 'A global e-commerce company stores customer PII in an Amazon S3-based data lake. Due to GDPR regulations, the company must be able to efficiently delete individual customer data upon request (right-to-erasure). The current data lake uses standard S3 objects. Which approach would best support compliant and efficient data deletion workflows?', '["Implement the data lake using Apache Iceberg tables, which support row-level deletes.","Configure Amazon S3 Object Lock on the S3 buckets to prevent any data deletion.","Manually scan and delete individual S3 objects corresponding to a customer''s PII.","Delete entire S3 prefixes that might contain a customer''s PII, even if it affects other data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the requirement for efficient and compliant data deletion. Apache Iceberg is an open table format for large analytic datasets that supports row-level deletes and updates, making it suitable for implementing GDPR right-to-erasure workflows in an S3-based data lake. Option B (incorrect) represents anti-pattern [ap-4.3-001] by preventing deletion, which directly conflicts with the right-to-erasure requirement. Option C (incorrect) is inefficient, error-prone, and not scalable for large data lakes. Option D (incorrect) is too broad and would lead to unintended data loss, violating data integrity principles.', 35, 'm_35_5', 17, NULL, NULL),
  ('mock_32_all_1775005113845', 'A data analytics department needs to share a specific dataset from its Amazon Redshift data warehouse with a marketing department in a separate AWS account. The requirement is to provide secure, read-only access to the data without creating copies or managing complex ETL processes for data transfer. Which Amazon Redshift feature should be utilized?', '["Amazon Redshift data sharing.","Exporting the data to Amazon S3 and granting cross-account S3 access.","Creating a read replica of the Redshift cluster in the marketing department''s account.","Using AWS Data Exchange to publish the dataset as a data product."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the purpose-built solution for this scenario. Amazon Redshift data sharing allows you to securely share live data from a Redshift data warehouse with other Redshift clusters or Redshift Serverless workgroups in the same or different AWS accounts, without copying or moving data. This meets the requirements for secure, read-only access without ETL. Option B (incorrect) involves creating data copies and managing ETL, which is less efficient and increases operational overhead. Option C (incorrect) is not a standard Redshift feature for sharing data across accounts, and read replicas are typically for high availability within an account. Option D (incorrect) is for commercial data product exchange, not internal departmental data sharing.', 35, 'm_35_5', 18, NULL, NULL),
  ('mock_32_all_1775005113845', 'A compliance team needs to ensure that all new and existing data uploaded to an Amazon S3 data lake is continuously scanned for sensitive information, such as PII and financial data. They require automated alerts and detailed reports on any sensitive data discovered to maintain regulatory compliance. Which AWS service should be implemented for this continuous monitoring?', '["AWS CloudTrail for S3 data events.","AWS Lake Formation.","Amazon Macie.","AWS Config rules for S3 bucket settings."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate service for continuous discovery and reporting of sensitive data in Amazon S3. Amazon Macie uses machine learning and pattern matching to identify and classify sensitive data, such as PII, and provides automated alerts and detailed findings. Option A (incorrect) logs API activity but does not analyze the content of S3 objects for sensitive data. Option B (incorrect) is for managing access control and permissions for data lakes, not for discovering sensitive data within objects. Option D (incorrect) tracks changes to S3 bucket configurations but does not analyze the content of the data stored within the buckets.', 35, 'm_35_5', 19, NULL, NULL),
  ('mock_32_all_1775005113845', 'A company is undergoing a PCI DSS compliance audit and needs to provide evidence that its AWS environment adheres to security best practices. The audit requires collecting specific configuration details, activity logs, and access policies across multiple AWS services. Which AWS service can help automate the collection and organization of this compliance evidence?', '["AWS CloudTrail for API activity logging.","AWS Config for resource configuration tracking.","AWS Audit Manager.","Amazon CloudWatch Logs for application and system logs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is specifically designed to automate the collection and organization of evidence for compliance audits. AWS Audit Manager helps you continuously audit your AWS usage to simplify risk assessments and compliance with regulations and industry standards like PCI DSS. It collects evidence from various AWS services (like CloudTrail, Config) and maps it to controls in a framework. Option A (incorrect) provides raw API activity logs but does not automate evidence collection and mapping to controls. Option B (incorrect) tracks resource configuration changes but doesn''t automate the compilation of audit evidence across multiple services for a specific framework. Option D (incorrect) is for collecting and monitoring application and system logs, not for automating compliance evidence collection.', 35, 'm_35_5', 20, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 20
WHERE id = 'mock_32_all_1775005113845';

