INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775006410483', 'A financial analytics company needs to store petabytes of historical transaction data for complex analytical queries. Data is loaded daily in large batches, and analysts perform ad-hoc queries on various dimensions. The primary requirement is to achieve the MOST cost-effective solution for large-scale OLAP workloads while maintaining query performance.', '["Option A: Ingest data into Amazon Redshift, leveraging its columnar storage and massively parallel processing for analytical queries.","Option B: Store data in Amazon DynamoDB with a complex secondary index structure to support ad-hoc analytical queries.","Option C: Utilize Amazon RDS for PostgreSQL to store the data, scaling up instances as needed to handle query load.","Option D: Store all data in Amazon S3 and use AWS Lambda functions to process queries directly on the S3 objects."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable choice. Amazon Redshift is a fully managed, petabyte-scale data warehouse service optimized for analytical workloads (OLAP) over large datasets. Its columnar storage and massively parallel processing (MPP) architecture provide high performance for complex queries and are cost-effective for petabyte-scale data. Option B (incorrect) is an anti-pattern (ap-2.1-001) because Amazon DynamoDB is a NoSQL key-value and document database optimized for high-performance transactional workloads (OLTP) with predictable latency, not complex analytical queries over petabytes of historical data. Option C (incorrect) is also an anti-pattern (ap-2.1-001) as Amazon RDS for PostgreSQL is designed for transactional (OLTP) workloads, not large-scale analytical processing, and would become prohibitively expensive and perform poorly for petabytes of data. Option D (incorrect) would introduce significant operational overhead and complexity for managing query execution and performance, making it less cost-effective and efficient compared to a dedicated data warehouse like Amazon Redshift.', 33, 'm_33_1', 1, NULL, NULL),
  ('mock_32_all_1775006410483', 'A global e-commerce platform requires a database to store customer shopping cart data. Each cart has a unique ID, and operations involve frequent reads and writes of individual cart items, requiring consistent, single-digit millisecond latency at any scale. The solution must support millions of concurrent users and scale automatically with demand.', '["Option A: Implement Amazon RDS for MySQL with read replicas to handle the high read traffic and ensure data consistency.","Option B: Use Amazon DynamoDB as a key-value store, leveraging its provisioned throughput and automatic scaling capabilities.","Option C: Store shopping cart data in Amazon Redshift, utilizing its analytical capabilities for real-time cart analysis.","Option D: Deploy Amazon OpenSearch Service to store and retrieve cart data, optimizing for full-text search on cart contents."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the ideal solution. Amazon DynamoDB is a fully managed NoSQL database service that provides fast and predictable performance with seamless scalability. Its key-value data model is perfect for storing shopping cart data, where each cart has a unique ID, and operations require low-latency reads and writes at any scale. Option A (incorrect) would struggle to meet the single-digit millisecond latency requirement at ''any scale'' for millions of concurrent users without significant operational overhead and complex sharding, as relational databases are not designed for this specific access pattern at such extreme scale. Option C (incorrect) is an anti-pattern (ap-2.1-001) because Amazon Redshift is an OLAP data warehouse, not suitable for high-throughput, low-latency transactional key-value operations. Option D (incorrect) is designed for full-text search and log analytics, not for transactional key-value storage and retrieval of shopping cart data, making it an inappropriate choice for this workload.', 33, 'm_33_1', 2, NULL, NULL),
  ('mock_32_all_1775006410483', 'A company is building a new application that processes customer orders. Each order involves multiple line items, requires strong transactional consistency (ACID properties), and needs to maintain complex relationships between customers, orders, and products. The data volume is expected to grow steadily, and the company prefers a managed relational database solution.', '["Option A: Store all order data in Amazon DynamoDB, using its flexible schema to represent relational structures.","Option B: Use Amazon S3 as the primary data store for order records, with custom application logic to manage relationships and transactions.","Option C: Deploy Amazon RDS for PostgreSQL to manage customer, order, and product data, leveraging its transactional capabilities.","Option D: Ingest all order data into Amazon Redshift for real-time transactional processing and complex joins."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate choice. Amazon RDS for PostgreSQL provides a fully managed relational database service that supports ACID transactions, complex relationships, and standard SQL queries, which are essential for managing customer order data. Option A (incorrect) is an anti-pattern (ap-2.1-002) as Amazon DynamoDB is a NoSQL database optimized for key-value and document workloads, and while it can model some relational patterns, it''s not ideal for complex relational data requiring strong ACID properties across multiple entities without significant application-level complexity. Option B (incorrect) would require building extensive custom logic for transaction management, data integrity, and relationship enforcement, which is complex, error-prone, and increases operational overhead. Option D (incorrect) is an anti-pattern (ap-2.1-001) because Amazon Redshift is an OLAP data warehouse, not designed for high-volume transactional (OLTP) workloads that require frequent inserts, updates, and deletes with strong transactional consistency.', 33, 'm_33_1', 3, NULL, NULL),
  ('mock_32_all_1775006410483', 'A research team collects vast amounts of unstructured and semi-structured sensor data from IoT devices. This data needs to be stored cost-effectively for long-term retention and occasionally queried by data scientists using tools like Amazon Athena. The data volume is unpredictable, ranging from gigabytes to terabytes daily, and the team wants to build a data lake with minimal upfront infrastructure cost.', '["Option A: Store all sensor data in Amazon RDS for MySQL, scaling storage and compute as data volumes increase.","Option B: Use Amazon Redshift to ingest and store the sensor data, leveraging its analytical query capabilities.","Option C: Store the sensor data in Amazon DynamoDB, using its flexible schema for semi-structured data and on-demand capacity.","Option D: Store the sensor data in Amazon S3 and catalog it with AWS Glue Data Catalog, enabling queries with Amazon Athena."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most suitable approach. Amazon S3 is ideal for building a data lake due to its virtually unlimited scalability, high durability, and cost-effectiveness for storing unstructured and semi-structured data. Cataloging the data with AWS Glue Data Catalog allows services like Amazon Athena to query it directly, providing a serverless and cost-effective analytics solution without managing infrastructure. Option A (incorrect) is an anti-pattern (ap-2.1-002) because Amazon RDS is a relational database not optimized for storing petabytes of unstructured/semi-structured data cost-effectively, and scaling it to handle unpredictable, massive volumes would be very expensive. Option B (incorrect) is designed for structured OLAP workloads and would be overly complex and expensive for raw, unstructured sensor data that needs to be stored and occasionally queried. Option C (incorrect) is a NoSQL database optimized for key-value/document workloads with predictable access patterns and would not be cost-effective for petabyte-scale storage of raw, infrequently accessed sensor data.', 33, 'm_33_1', 4, NULL, NULL),
  ('mock_32_all_1775006410483', 'A company processes millions of log entries daily from various applications. These logs need to be stored, indexed, and made searchable for operational troubleshooting and security analysis. Analysts require the ability to perform full-text searches, aggregate data, and visualize trends with low latency. The solution should be fully managed to minimize operational overhead.', '["Option A: Ingest all log data into Amazon OpenSearch Service, leveraging its search and analytics capabilities.","Option B: Store log entries in Amazon S3 and use AWS Glue crawlers to catalog the data for querying with Amazon Athena.","Option C: Store log data in Amazon DynamoDB with a global secondary index to enable efficient search operations.","Option D: Utilize Amazon Redshift to store log data, performing complex SQL queries for full-text search and aggregation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution. Amazon OpenSearch Service is a fully managed service that makes it easy to deploy, operate, and scale OpenSearch clusters. It is specifically designed for log analytics, full-text search, and real-time application monitoring, providing low-latency search and powerful aggregation capabilities. Option B (incorrect) is suitable for analytical queries on structured/semi-structured data in a data lake but lacks the real-time indexing, full-text search, and visualization features inherent to OpenSearch Service, making it less efficient for operational troubleshooting. Option C (incorrect) is a NoSQL key-value database, not optimized for full-text search or complex aggregations over log data, and would require significant custom development to replicate OpenSearch''s capabilities. Option D (incorrect) is an OLAP data warehouse primarily for structured analytical queries, not for high-volume, real-time full-text search and indexing of log data, which would be inefficient and costly.', 33, 'm_33_1', 5, NULL, NULL);

