-- Module: m_35_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775006410483', 'A company needs to track all data access events for sensitive customer data stored in Amazon S3 buckets, including who accessed what, when, and from where. This audit trail is critical for compliance and forensic analysis, requiring centralized storage and retention for 7 years with MINIMAL operational overhead.', '["Enable AWS CloudTrail data events for the S3 buckets, configure CloudTrail to deliver logs to an S3 bucket, and set up an S3 Lifecycle policy for 7-year retention.","Enable S3 server access logging for the S3 buckets, delivering logs to a separate S3 bucket, and use Amazon Athena to query the logs for analysis.","Implement custom logging within applications that access S3, sending logs to Amazon CloudWatch Logs, and then exporting them to S3 for long-term retention.","Configure Amazon Macie to monitor S3 buckets for sensitive data access patterns and generate alerts, storing these alerts in Amazon CloudWatch for auditing."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most comprehensive and integrated solution with minimal operational overhead. AWS CloudTrail data events capture detailed S3 object-level API activity (GetObject, PutObject, DeleteObject), including who accessed what, when, and from where. Delivering these logs to an S3 bucket and using S3 Lifecycle policies ensures cost-effective long-term retention. Option B (incorrect) uses S3 server access logging, which provides valuable information but is less integrated with AWS identity and access management than CloudTrail, and requires more manual effort for comprehensive auditing across AWS services. Option C (incorrect) involves developing and maintaining custom application-level logging, which significantly increases operational overhead and may not capture all direct S3 access events. Option D (incorrect) uses Amazon Macie for sensitive data discovery and alerting, which is a different use case than comprehensive access auditing, and does not provide the detailed audit trail required.', 35, 'm_35_4', 14, NULL, NULL),
  ('mock_32_all_1775006410483', 'A company stores sensitive customer data in an Amazon S3 data lake, with metadata registered in AWS Glue Data Catalog. Various internal departments require different levels of access, from full table access to specific column-level permissions. The solution must provide fine-grained authorization and be centrally managed for compliance.', '["Attach IAM policies directly to individual IAM users and roles, granting specific S3 object-level permissions and Glue Data Catalog access.","Implement AWS Lake Formation to define and manage table-level and column-level permissions on Glue Data Catalog resources, integrating with IAM roles for user authorization.","Use Amazon S3 bucket policies to control access to different prefixes within the data lake, mapping prefixes to departments.","Create separate Amazon S3 buckets for each department, replicating relevant data to each bucket and managing access via bucket policies."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective solution. AWS Lake Formation provides a centralized, fine-grained security model for data lakes, allowing administrators to define table-level, column-level, and row-level permissions directly on Glue Data Catalog resources. This integrates seamlessly with IAM roles, simplifying management and ensuring compliance. Option A (incorrect) would lead to a complex and unscalable permission management system, as individual IAM policies would need to be crafted and maintained for every user and every resource, increasing administrative overhead. Option C (incorrect) represents an anti-pattern (ap-4.1-001). S3 bucket policies offer only object-level or prefix-level granularity, which is insufficient for column-level security and does not integrate with the Glue Data Catalog''s metadata. Option D (incorrect) would result in significant data duplication, increased storage costs, and potential data consistency issues, making it an inefficient and complex approach for fine-grained authorization.', 35, 'm_35_4', 15, NULL, NULL),
  ('mock_32_all_1775006410483', 'A financial services company needs to process large volumes of transaction data stored in Amazon S3, some of which contains sensitive account numbers and PII. They require an automated solution to continuously discover and identify this sensitive data within their S3 buckets to ensure compliance with data privacy regulations, with minimal operational overhead.', '["Use Amazon Macie to automatically discover, classify, and report on sensitive data, including PII, stored in Amazon S3 buckets.","Manually review S3 object contents periodically to identify sensitive data patterns and tag objects accordingly.","Develop custom AWS Glue ETL jobs with Python scripts to scan S3 objects for PII patterns and store findings in a separate database.","Implement S3 server-side encryption with AWS KMS for all buckets, ensuring all data is encrypted at rest."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable solution. Amazon Macie is a fully managed data security and data privacy service that uses machine learning and pattern matching to discover and protect sensitive data in AWS. It automates the process of identifying PII and other sensitive information in S3, providing continuous monitoring with minimal operational overhead. Option B (incorrect) is a manual process that is not scalable, highly error-prone, and does not meet the requirement for an automated solution for large volumes of data. Option C (incorrect) involves significant development and operational overhead to build, maintain, and run custom ETL jobs for PII detection, which is less efficient than a managed service like Macie. Option D (incorrect) ensures data encryption at rest, which is a crucial security measure, but it does not discover or identify the presence of sensitive data within the encrypted objects, failing the core requirement of PII discovery.', 35, 'm_35_4', 16, NULL, NULL),
  ('mock_32_all_1775006410483', 'A data analytics department needs to share a curated dataset from their Amazon Redshift cluster with an external research institution. The institution has its own AWS account. The data must be shared securely, without creating copies, and with granular control over which tables and schemas are accessible to the institution.', '["Export the dataset to Amazon S3, encrypt it with AWS KMS, and grant cross-account access to the S3 bucket using an S3 bucket policy.","Utilize Amazon Redshift data sharing to create a datashare, specifying the schemas and tables to be shared, and authorize the research institution''s AWS account to consume it.","Create a separate Amazon Redshift cluster for the research institution, replicate the data to it, and manage access within that cluster.","Set up AWS Data Exchange as a data provider, package the dataset, and allow the research institution to subscribe to the data product."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate solution. Amazon Redshift data sharing enables secure, live sharing of data from a Redshift cluster with other Redshift clusters or Redshift Spectrum users in different AWS accounts. It provides granular control over schemas and tables, eliminates data duplication, and ensures data remains within the Redshift environment. Option A (incorrect) would involve creating a copy of the data in Amazon S3, increasing storage costs and management overhead, and potentially introducing data freshness issues. Option C (incorrect) would incur significant infrastructure costs and operational overhead for maintaining a separate Redshift cluster and managing data replication. Option D (incorrect) is a valid service for data sharing, but AWS Data Exchange is typically designed for commercial data products and broader distribution, not for direct, private sharing with a single, known research institution, making it less suitable for this specific, targeted sharing requirement.', 35, 'm_35_4', 17, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_35_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_32_all_1775006410483', 'A healthcare provider stores patient records in an Amazon S3 data lake. They need an automated solution to regularly scan these S3 buckets to identify and report any accidental storage of unencrypted Personally Identifiable Information (PII) or Protected Health Information (PHI). The solution must automate PII/PHI discovery and reporting with the LEAST manual effort.', '["Configure Amazon Macie to perform automated sensitive data discovery jobs across the S3 buckets and generate findings for review.","Develop custom AWS Lambda functions to scan S3 objects, apply regular expressions to identify PII/PHI patterns, and log findings to Amazon CloudWatch.","Use AWS Lake Formation to define data catalog entries for the S3 data, and then manually review metadata for PII/PHI indicators.","Enable S3 Object Lock on the S3 buckets to prevent accidental deletion of sensitive data, and rely on periodic manual audits."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution for automated PII/PHI discovery with the least manual effort. Amazon Macie is a fully managed data security and data privacy service that uses machine learning and pattern matching to discover, classify, and protect sensitive data in AWS. It automatically detects sensitive data, including PII and PHI, in S3 buckets and generates detailed findings. Option B (incorrect) involves significant development and maintenance overhead for custom Lambda functions and pattern matching, violating the ''LEAST manual effort'' constraint. Option C (incorrect) uses AWS Lake Formation for data cataloging and permissions, but it does not inherently provide automated PII/PHI discovery; it would still require manual review or integration with other services. Option D (incorrect) uses S3 Object Lock for data immutability, which is a data integrity feature, not a PII/PHI discovery and reporting mechanism. Relying on manual audits is also against the ''automated'' and ''least manual effort'' constraints.', 35, 'm_35_5', 18, NULL, NULL),
  ('mock_32_all_1775006410483', 'A company needs to maintain an immutable audit trail of all API calls made to AWS services within their account for compliance and security forensics. This audit trail must be retained for a minimum of seven years and be protected against accidental or malicious alteration.', '["Store AWS CloudTrail logs in Amazon CloudWatch Logs for seven years, configuring appropriate retention policies.","Configure AWS CloudTrail to deliver logs to an Amazon S3 bucket, and enable S3 Object Lock in compliance mode for the bucket with a retention period of seven years.","Use AWS Audit Manager to collect compliance evidence and store it for seven years.","Enable AWS Config to track resource configuration changes and store the history in an S3 bucket with versioning enabled."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most robust solution for an immutable audit trail. AWS CloudTrail logs all API calls, and delivering these logs to an Amazon S3 bucket with S3 Object Lock enabled in compliance mode ensures that the logs cannot be overwritten or deleted by any user, including the root account, for the specified retention period. Option A (incorrect) stores logs in CloudWatch Logs, but CloudWatch Logs does not offer the same level of immutability guarantee as S3 Object Lock in compliance mode, and its retention policies are less suited for strict immutability requirements. Option C (incorrect) is designed for collecting compliance evidence and automating audits, but it does not provide the raw, immutable API call logs that CloudTrail does. Option D (incorrect) tracks configuration changes, not API calls, and while S3 versioning helps with data recovery, it doesn''t provide the same immutability guarantees as S3 Object Lock compliance mode for audit trails.', 35, 'm_35_5', 19, NULL, NULL),
  ('mock_32_all_1775006410483', 'A company needs to ensure that all Amazon S3 buckets containing sensitive data have server-side encryption enabled and that public access is strictly blocked. They require an automated mechanism to continuously audit and report on compliance with these security configurations across their AWS accounts.', '["Manually review the configuration of each Amazon S3 bucket periodically to check for encryption and public access settings.","Enable AWS CloudTrail to log all S3 API calls and analyze these logs for configuration changes related to encryption and public access.","Implement AWS Config rules to continuously monitor Amazon S3 bucket configurations for encryption status and public access settings, generating compliance reports.","Use Amazon Macie to discover sensitive data within S3 buckets and then manually verify their encryption and public access status."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution for continuous auditing and reporting on AWS resource configurations. AWS Config allows you to define rules that continuously evaluate the configuration of your AWS resources against desired settings, such as S3 bucket encryption and public access blocks. It automatically generates compliance reports and can trigger alerts for non-compliant resources. Option A (incorrect) is a manual process that is not scalable, prone to human error, and does not provide continuous auditing or automated reporting. Option B (incorrect) logs API calls (management events), which can show *when* a configuration change was made, but it does not provide a continuous, automated compliance assessment against a desired state like AWS Config. Option D (incorrect) is designed for discovering and classifying sensitive *data content* within S3, not for auditing the *configuration* of the S3 buckets themselves for encryption or public access settings.', 35, 'm_35_5', 20, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 20
WHERE id = 'mock_32_all_1775006410483';

